final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"os"
	"strings"
)

func main() {
	readInt()
	readInt()
	source := readToken()
	zeros := strings.Count(source, "0")
	prefix := make([]int, len(source))
	ones := 0
	for i := range source {
		if source[i] == '1' {
			ones++
		}
		prefix[i] = ones
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for t := 0; ; t++ {
		query := readToken()
		if query == "" {
			break
		}
		need, available := zeros-strings.Count(query, "0"), strings.Count(query, "?")
		valid := 0 <= need && need <= available
		total := 0
		for i := 0; valid && i < len(query); i++ {
			c := query[i]
			if c == '?' { // earliest ? become the missing 0s
				if need > 0 {
					c = '0'
					need--
				} else {
					c = '1'
				}
			}
			if c == '1' {
				total++
			}
			if total > prefix[i] {
				valid = false
			}
		}
		if t > 0 {
			w.WriteByte(' ')
		}
		if valid {
			w.WriteString("YES")
		} else {
			w.WriteString("NO")
		}
	}
	w.WriteByte('\n')
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
